package android.content;import java.util.*;public class ContentValues {public final LinkedHashMap<String,Object> values=new LinkedHashMap<>();public void put(String k,String v){values.put(k,v);}public void put(String k,Integer v){values.put(k,v);}public void put(String k,Long v){values.put(k,v);}public String getAsString(String k){Object v=values.get(k);return v==null?null:v.toString();}public Long getAsLong(String k){String v=getAsString(k);return v==null?null:Long.valueOf(v);}public boolean containsKey(String k){return values.containsKey(k);}}
